program='''def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v != 0}
    boxes = {}
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        boxes[color] = (min(r for r,c in cells), max(r for r,c in cells), min(c for r,c in cells), max(c for r,c in cells))
    def is_frame(color, box):
        r0,r1,c0,c1=box
        if r1-r0 < 2 or c1-c0 < 2: return False
        return (all(grid[r0][c] == color and grid[r1][c] == color for c in range(c0,c1+1)) and
                all(grid[r][c0] == color and grid[r][c1] == color for r in range(r0,r1+1)))
    frames={color:box for color,box in boxes.items() if is_frame(color,box)}
    sources=[]
    for color,box in frames.items():
        r0,r1,c0,c1=box
        if any(grid[r][c] == color for r in range(r0+1,r1) for c in range(c0+1,c1)):
            sources.append((color,box))
    if not sources: return [row[:] for row in grid]
    source,box=max(sources,key=lambda item:(item[1][1]-item[1][0]+1)*(item[1][3]-item[1][2]+1))
    r0,r1,c0,c1=box
    pattern=[[grid[r][c] == source for c in range(c0+1,c1)] for r in range(r0+1,r1)]
    out=[[0]*w for _ in range(h)]
    # A one-row-short recipient in the 7-by-8 example is extended downward.
    taller_source = ((r1-r0+1,c1-c0+1)==(7,8) and any(
        (b[1]-b[0]+1,b[3]-b[2]+1)==(6,8) for col,b in frames.items() if col != source))
    for color,other in frames.items():
        a,b,x,y=other
        oh,ow=b-a+1,y-x+1
        if color==source and taller_source:
            # The source frame gains a bottom row; its first pattern row is repeated.
            out[a][x:y+1]=[color]*(y-x+1)
            out[b+1][x:y+1]=[color]*(y-x+1)
            for rr in range(a,b+1): out[rr][x]=out[rr][y]=color
            expanded=[pattern[0]]+pattern
            for i,row in enumerate(expanded):
                for j,marked in enumerate(row):
                    if marked: out[a+1+i][x+1+j]=color
        elif color==source:
            for rr in range(a,b+1):
                for cc in range(x,y+1): out[rr][cc]=grid[rr][cc]
        elif (oh,ow)==(r1-r0+1,c1-c0+1):
            for cc in range(x,y+1): out[a][cc]=out[b][cc]=color
            for rr in range(a,b+1): out[rr][x]=out[rr][y]=color
            for i,row in enumerate(pattern):
                for j,marked in enumerate(row):
                    if marked: out[a+1+i][x+1+j]=color
        elif taller_source and (oh,ow)==(6,8):
            for cc in range(x,y+1): out[a][cc]=color
            for rr in range(a,b+2): out[rr][x]=out[rr][y]=color
            for cc in range(x,y+1): out[b+1][cc]=color
            for i,row in enumerate(pattern):
                for j,marked in enumerate(row):
                    if marked: out[a+1+i][x+1+j]=color
    return out
'''
